ST.say(S,{actors:[p],tag:p.goReport?'今日こそ':'また乗ってしまう',text:fm(pk(S,p.goReport?D.SILENT_GO:D.SILENT_AGAIN),V),why:p.name+'は昨日、言い出せなかった'+(p.goReport?'。今日こそ言うと決めた':'')});
