if(p.state==='norm'&&p.m.doubt>=30){p.state='doubt';p.cnt.notice++;ST.say(S,{actors:[p],tag:'違和感',text:fm(pk(S,D.NOTICE[ps(p)]),V),why:p.name+'の違和感 '+Math.round(p.m.doubt),mag:14});return;}
if(p.state!=='doubt')return;
